/* The Vietnamese dictionary, lifted verbatim out of templates/index.html.
 *
 * It was 145 KB gzipped inside the boot document — 12% of everything the browser downloaded to
 * show a login screen — and it was built on every load, including for the English users who are
 * the default and who never read a key of it.
 *
 * KEY ORDER IS LOAD-BEARING and must be preserved on any edit: this is one flat object shared by
 * the whole portal, so a duplicate key silently takes the LAST value. tests/vi_duplicate_keys.js
 * reads THIS file now and fails on a repeat.
 *
 * Assigned to window on purpose. index.html declares `var _VI = {}` at top level, and a top-level
 * `var` IS the window property, so this replaces the placeholder that every _t() call reads. */
