  "A draft is a working document, not a baseline. Set this estimate to Approved or Won first.": "Bản nháp là tài liệu đang làm, chưa phải mốc chuẩn. Hãy chuyển dự toán sang Đã duyệt hoặc Trúng thầu trước.",
  "A price is built by the commercial team and committed by management. Setting a project budget needs Approver level.": "Giá do bộ phận thương mại lập và ban lãnh đạo cam kết. Đặt ngân sách dự án cần cấp Phê duyệt.",
  "A rate used in an estimate is COPIED into it, never referenced. A tender reopened six months later must still be the tender that was submitted — so updating a price here never reprices work already estimated. Where a price has moved, the estimate says so and offers to re-price.": "Đơn giá dùng trong dự toán được SAO CHÉP vào, không tham chiếu động. Hồ sơ thầu mở lại sau sáu tháng vẫn phải đúng như lúc nộp — nên cập nhật giá ở đây không bao giờ tính lại phần đã lập. Nếu giá đã thay đổi, dự toán sẽ báo và đề nghị tính lại.",
