  "EXW → international leg → CIF → converted at the rate for that supplier’s currency → duty → special consumption tax → VAT → local charges → landed cost. The three taxes CASCADE: duty on CIF, SCT on CIF plus duty, VAT on all three. Import VAT is recoverable and never enters the cost.": "EXW → chặng quốc tế → CIF → quy đổi theo tỷ giá của đồng tiền nhà cung cấp → thuế nhập khẩu → thuế TTĐB → VAT → chi phí nội địa → giá vốn nhập kho. Ba sắc thuế TÍNH CHỒNG LÊN NHAU: thuế NK trên CIF, TTĐB trên CIF cộng thuế NK, VAT trên cả ba. VAT nhập khẩu được khấu trừ nên không bao giờ vào giá vốn.",
  "Edit the tender": "Sửa hồ sơ thầu",
