  "Every material this bill needs, gathered across all its lines and including the waste allowance. This is the list procurement would otherwise rebuild by hand from the drawings.": "Toàn bộ vật liệu bảng khối lượng này cần, tổng hợp từ mọi dòng và đã gồm hao hụt. Đây chính là danh sách mà bộ phận mua hàng lẽ ra phải tự bóc lại từ bản vẽ.",
  "Every rate this tender prices with, in one place. Change one and every line reprices — the same way the workbook’s named ranges flow through. Percentages are PERCENTAGES: 0.5 means half a percent, not half.": "Mọi tỷ lệ hồ sơ thầu này dùng, gom về một chỗ. Đổi một giá trị là mọi dòng tính lại — đúng như các named range trong file Excel. Phần trăm là PHẦN TRĂM: 0.5 nghĩa là nửa phần trăm, không phải một nửa.",
  "Fill these in before this is a document rather than a draft": "Hãy điền các mục sau để đây là một tài liệu chứ không phải bản nháp",
