  "It can only be done once. Re-baselining a live job afterwards needs a revised estimate.": "Chỉ làm được một lần. Muốn đặt lại mốc chuẩn cho một công trình đang chạy thì phải lập dự toán sửa đổi.",
  "Line item": "Khoản mục",
  "Margin": "Biên lợi nhuận",
  "Margin basis: the profit percentage is a share OF the selling price. Price = cost ÷ (1 − p).": "Cơ sở tỷ suất: phần trăm lợi nhuận là phần TRÊN giá bán. Giá = giá thành ÷ (1 − p).",
  "Mark-up basis: the profit percentage is added ON to the cost. Price = cost × (1 + p). A 20% mark-up takes a 16.7% margin, not 20%.": "Cơ sở cộng giá: phần trăm lợi nhuận được CỘNG vào giá thành. Giá = giá thành × (1 + p). Cộng 20% chỉ cho tỷ suất 16,7%, không phải 20%.",
