  "Pick a project first.": "Hãy chọn một dự án trước.",
  "Priced resources on file": "Nguồn lực đã có đơn giá",
  "Profit as a share of the selling price — the number the business lives on": "Lợi nhuận tính trên giá bán — con số doanh nghiệp sống bằng nó",
  "Quotation details": "Thông tin báo giá",
  "Quotation info": "Thông tin báo giá",
  "Recoverable from the state — deliberately NOT part of the landed cost": "Được hoàn/khấu trừ từ ngân sách — cố ý KHÔNG nằm trong giá vốn",
  "SALES QUOTATION": "BẢNG BÁO GIÁ",
  "Section": "Chương",
  "Sections and notes carry no money — only priced items do. Open a line to build its rate from material, labour, plant and subcontract.": "Chương và ghi chú không mang giá trị — chỉ hạng mục có giá mới mang. Mở một dòng để bóc đơn giá từ vật liệu, nhân công, máy và thầu phụ.",
  "Sell": "Giá bán",
  "Selling rate — direct cost plus this line’s share of preliminaries, overhead, risk and profit": "Đơn giá bán — chi phí trực tiếp cộng phần chia của dòng này trong chi phí chung, quản lý, dự phòng và lợi nhuận",
  "Set the project budget": "Đặt ngân sách dự án",
  "Subtotal (excl VAT)": "Cộng (chưa VAT)",
  "Switch a production line off and it leaves the quotation entirely — not as a zero row, which a customer reads as “we forgot to price this”. Capacity scale multiplies QUANTITY, not unit price: half a line is half the equipment at the same price. The permanent plant cannot be switched off.": "Tắt một dây chuyền thì nó biến mất hoàn toàn khỏi báo giá — không để lại dòng bằng 0, vì khách hàng sẽ hiểu là “họ quên báo giá mục này”. Hệ số công suất nhân với KHỐI LƯỢNG, không phải đơn giá: nửa dây chuyền là nửa số thiết bị với cùng đơn giá. Phần nhà máy cố định không thể tắt.",
  "Terms &amp; conditions": "Điều khoản &amp; điều kiện",
  "The quotation would price whichever came first — give them different codes.": "Báo giá sẽ lấy mã nào xuất hiện trước — hãy đặt mã khác nhau.",
  "The same item code is bought two ways": "Cùng một mã hàng được mua theo hai đường",
  "The server could not price this estimate": "Máy chủ không tính được giá cho dự toán này",
  "This estimate is the budget of a live project — raise a revised estimate instead.": "Dự toán này đang là ngân sách của một dự án đang chạy — hãy lập dự toán sửa đổi.",
  "This estimate is the budget of a live project. Re-baselining is a decision, not a re-click — raise a revised estimate instead.": "Dự toán này đang là ngân sách của một dự án đang chạy. Đặt lại mốc chuẩn là một quyết định, không phải bấm lại — hãy lập dự toán sửa đổi.",
  "This estimate still prices at what it was priced at — that is deliberate. Re-pricing is a decision you make, not something that happens to a submitted tender.": "Dự toán vẫn giữ đúng giá lúc lập — đó là chủ ý. Tính lại giá là quyết định của bạn, không phải điều tự xảy ra với một hồ sơ đã nộp.",
  "This is exactly what the customer will receive. Nothing here shows cost or mark-up.": "Đây đúng là những gì khách hàng sẽ nhận. Không có chỗ nào hiện giá vốn hay tỷ lệ cộng giá.",
  "This is what becomes the project budget if the tender is won": "Đây là con số trở thành ngân sách dự án nếu trúng thầu",
  "This rate was typed, not built from resources. Legitimate under tender pressure — but the total says so.": "Đơn giá này được nhập tay, không bóc từ định mức. Chấp nhận được khi gấp — nhưng tổng số sẽ nói rõ điều đó.",
  "This tender is the budget of a live project — raise a revised one instead.": "Hồ sơ thầu này đang là ngân sách của một dự án đang chạy — hãy lập bản sửa đổi.",
  "This writes the cost base of": "Thao tác này ghi giá thành của",
  "Total cost": "Tổng chi phí",
  "Total landed": "Tổng giá vốn nhập kho",
  "Total material": "Tổng vật liệu",
  "VAT (output)": "VAT đầu ra",
  "What a won tender hands to the job. The COST BASE becomes the budget — direct cost, preliminaries, overhead and risk. Profit is deliberately not budgeted: a project that spends its profit has not stayed within budget, it has consumed the reason the job was taken.": "Những gì một hồ sơ trúng thầu bàn giao cho công trình. GIÁ THÀNH trở thành ngân sách — chi phí trực tiếp, chi phí chung công trường, quản lý và dự phòng. Lợi nhuận cố ý không đưa vào ngân sách: dự án tiêu vào lợi nhuận không phải là giữ được ngân sách, mà là ăn mất lý do nhận việc.",
  "Which cost centres are carrying the job and which are being carried, against a 15% target margin. Mark-up and margin are different numbers and both are shown — a 15% mark-up is a 13% margin.": "Trung tâm chi phí nào đang gánh công trình và trung tâm nào đang được gánh, so với biên mục tiêu 15%. Cộng giá và tỷ suất là hai con số khác nhau và cả hai đều được hiển thị — cộng 15% chỉ cho tỷ suất 13%.",
  "Worth a second look before you send it": "Nên xem lại trước khi gửi",
  "a receivable, deliberately not in the cost": "một khoản phải thu, cố ý không nằm trong giá vốn",
  "as its budget:": "làm ngân sách:",
  "decided": "đã có kết quả",
  "effective mark-up": "tỷ lệ cộng giá thực tế",
  "estimated at": "lập giá tại",
  "every line built from its parts": "mọi dòng đều bóc từ thành phần",
  "ex-VAT": "chưa gồm VAT",
  "into": "vào",
  "labour hours": "giờ công",
  "library now": "thư viện hiện tại",
  "none decided yet": "chưa có kết quả nào",
  "not attributed to a category": "chưa quy về nhóm chi phí nào",
  "of cost on site": "của chi phí tại công trường",
  "of cost on site plus overhead": "của chi phí công trường cộng quản lý",
  "of direct cost": "của chi phí trực tiếp",
  "priced by entered rate": "định giá bằng đơn giá nhập tay",
  "priced lines": "dòng có giá",
  "the blended truth after any line-by-line discounting.": "con số thực sau khi đã giảm giá từng dòng.",
