  /* AHU Production (2026-08-20). Every key here is QUALIFIED — 'Production stage', not 'Stage'.
     _VI is one flat object shared by the whole portal, so a bare generic word is a claim on that
     word in every module and the later definition wins silently. See tests/vi_duplicate_keys.js. */
  'AHU Production': 'Sản xuất AHU',
