  'How an AHU gets built': 'Quy trình sản xuất một AHU',
  'Seven stages. Each ends at a gate that will not pass until its conditions are met, so a unit can only move forward in order. Click a stage to see the units in it.': 'Bảy công đoạn. Mỗi công đoạn kết thúc bằng một cổng chỉ mở khi đủ điều kiện, nên sản phẩm chỉ tiến theo đúng thứ tự. Bấm vào một công đoạn để xem sản phẩm đang ở đó.',
  'Show all stages': 'Xem tất cả công đoạn',
