  "Eurovent 6/18-2022, the European AHU industry's own quality criteria. Advisory — the SOP is what a gate refuses on.": 'Eurovent 6/18-2022, tiêu chí chất lượng do chính ngành AHU châu Âu đặt ra. Mang tính tham khảo — cổng công đoạn vẫn chỉ từ chối theo SOP.',
