  'Print this and hang it with the unit. Scanning a code opens that step on a phone or tablet, already signed in.': 'In thẻ này và treo cùng sản phẩm. Quét mã sẽ mở đúng bước đó trên điện thoại hoặc máy tính bảng, đã đăng nhập sẵn.',
