  'Leave the capacity blank and the chart reports hours with no verdict. That is deliberate — a chart drawn against a guessed capacity looks exactly like one drawn against a real one, and this is the number a delivery promise rests on.': 'Để trống năng lực thì biểu đồ chỉ báo số giờ mà không kết luận. Đây là chủ ý — biểu đồ vẽ theo một năng lực phỏng đoán trông y hệt biểu đồ vẽ theo năng lực thật, mà đây là con số mà cam kết giao hàng dựa vào.',
