  'notice is 120 days, not 45': 'thời hạn báo trước là 120 ngày, không phải 45 ngày',
  /* Occupational accidents (Law on OSH 2015 · Decree 39/2016). Keys already in this dict are
     deliberately not repeated — a later duplicate silently overrides the earlier one. */
  'A fatal accident, or a serious one injuring two or more people, must be declared to the labour inspectorate at once by the fastest means — not at the end of the week. This register works out which duty applies and when the investigation report is due.':
    'Tai nạn chết người, hoặc tai nạn nặng làm bị thương từ hai người trở lên, phải khai báo ngay với thanh tra lao động bằng phương tiện nhanh nhất — không để đến cuối tuần. Sổ này xác định nghĩa vụ nào áp dụng và khi nào phải có biên bản điều tra.',
