  'The Microsoft sign-in window did not open — allow pop-ups for this site, then re-attach the file.': 'Cửa sổ đăng nhập Microsoft không mở được — hãy cho phép pop-up cho trang này, rồi đính kèm lại tệp.',
  'Your Microsoft session expired — sign in to Microsoft 365 again, then re-attach the file.': 'Phiên Microsoft đã hết hạn — hãy đăng nhập lại Microsoft 365, rồi đính kèm lại tệp.',
