  'By signing you confirm you have received this company asset and are responsible for it until it is returned.': 'Bằng việc ký, bạn xác nhận đã nhận tài sản của công ty và chịu trách nhiệm cho đến khi hoàn trả.',
  'You are responsible for the company assets assigned to you. Please e-sign to acknowledge receipt of each item. On offboarding, all devices must be returned and signed off before your last working day.': 'Bạn chịu trách nhiệm với các tài sản công ty được cấp. Vui lòng ký điện tử để xác nhận đã nhận từng thiết bị. Khi nghỉ việc, tất cả thiết bị phải được hoàn trả và ký bàn giao trước ngày làm việc cuối cùng.',
