  'It stops appearing in My Space and stops being chased. Signatures already given stay on record and it can be restored at any time.': 'Tài liệu sẽ không còn hiển thị ở Không gian của tôi và không bị nhắc ký nữa. Các chữ ký đã có vẫn được lưu và có thể khôi phục bất cứ lúc nào.',
  'It goes back to everyone it applies to, and anyone who has not signed the current version will be asked again.': 'Tài liệu sẽ hiển thị lại với mọi người thuộc phạm vi áp dụng, và ai chưa ký phiên bản hiện tại sẽ được nhắc ký.',
  'Re-issue at a new version': 'Ban hành phiên bản mới', 'Re-issue at a new version?': 'Ban hành phiên bản mới?',
