  'The file includes personal data — ID numbers, dates of birth, addresses and emergency contacts. It leaves the portal’s access controls, so keep it on company storage and delete it when you are done. This export is recorded in the audit log.': 'Tệp này chứa dữ liệu cá nhân — số CCCD, ngày sinh, địa chỉ và liên hệ khẩn cấp. Tệp nằm ngoài phạm vi kiểm soát truy cập của hệ thống, vì vậy hãy lưu trên kho dữ liệu công ty và xóa sau khi dùng xong. Lần xuất này được ghi vào nhật ký kiểm toán.',
