  'Publishing a company document is for HR, Editors and Administrators — an administrator can add you under Access & Permissions.': 'Ban hành tài liệu công ty dành cho Nhân sự, cấp Người chỉnh sửa và Quản trị viên — quản trị viên có thể thêm bạn ở mục Phân quyền.',
