  'This overtime is over the statutory limit': 'Số giờ làm thêm này vượt giới hạn luật định',
  'would reach': 'sẽ lên tới',
  'The hours are not being deleted — they were worked. You can approve them anyway, but the approval will be recorded in the audit trail under your name with the reason you give.':
    'Số giờ này không bị xóa — người lao động đã làm thật. Bạn vẫn có thể duyệt, nhưng việc duyệt sẽ được ghi vào nhật ký kiểm toán dưới tên bạn kèm lý do bạn nêu.',
  'Reason for approving over the limit': 'Lý do duyệt vượt giới hạn',
  'e.g. emergency shutdown at the client site': 'ví dụ: dừng máy khẩn cấp tại công trình khách hàng',
  'Approve anyway': 'Vẫn duyệt', 'Please give a reason': 'Vui lòng nhập lý do',
