  // ── Rebuilding the employment history ──
  'Rebuild the employment history from the pay runs a Director has signed?': 'Xây dựng lại lịch sử nhân sự từ các bảng lương đã được Giám đốc ký?',
  'Reconstructed rows are removed and rebuilt. Anything recorded by hand is kept, and what is removed is written to the audit trail.': 'Các dòng suy luận sẽ được xóa và dựng lại. Những dòng do người dùng tự nhập vẫn được giữ nguyên, và phần bị xóa sẽ được ghi vào nhật ký kiểm toán.',
  'Rebuilding…': 'Đang dựng lại…', 'Rebuilt from': 'Đã dựng lại từ',
