  'reconstructed row(s) across': 'dòng suy luận, thuộc', 'employee(s)': 'nhân viên',
  'Nothing needed removing.': 'Không có dòng nào cần xóa.',
  'Wrote': 'Đã ghi', 'dated event(s)': 'sự kiện có ngày hiệu lực',
  'in the history in total': 'tổng số trong lịch sử', 'Note:': 'Lưu ý:',
  'line(s) predate the contractual salary being recorded, so they contributed no salary row — a gap is honest, a wrong figure is not.': 'dòng có trước khi mức lương hợp đồng được ghi nhận nên không tạo dòng lương — thiếu dữ liệu là trung thực, còn số liệu sai thì không.',
  'Employment history rebuilt': 'Đã dựng lại lịch sử nhân sự',
  // ── Annual leave entitlement (Art. 113/114) ──
  'Annual leave entitlement': 'Số ngày phép năm theo luật',
  'Labour Code Art. 113 — 12 days, 14 for hazardous work, 16 for especially hazardous · Art. 114 — one more day every 5 years · a first or final year is prorated (Decree 145/2020 Art. 66).':
    'Bộ luật Lao động Đ.113 — 12 ngày, 14 ngày với công việc nặng nhọc/độc hại, 16 ngày với đặc biệt nặng nhọc/độc hại · Đ.114 — thêm 1 ngày sau mỗi 5 năm · năm đầu hoặc năm cuối được tính theo tỷ lệ (NĐ 145/2020 Đ.66).',
  'Raise the': 'Nâng', 'short record(s)': 'hồ sơ còn thiếu',
  'Every record meets the statutory minimum.': 'Tất cả hồ sơ đều đạt mức tối thiểu luật định.',
  'employee(s) checked for': 'nhân viên đã kiểm tra cho năm',
  'record(s) below the statutory minimum': 'hồ sơ thấp hơn mức tối thiểu luật định',
  'These employees are entitled to more annual leave than their record gives them. Raising a record does not change any leave already taken.':
    'Những nhân viên này được hưởng số ngày phép nhiều hơn mức ghi trên hồ sơ. Việc nâng hồ sơ không làm thay đổi số ngày phép đã sử dụng.',
  'On record': 'Trên hồ sơ', 'Required by law': 'Luật yêu cầu', 'How it is made up': 'Cách tính',
  'short by': 'thiếu', 'base': 'cơ bản', 'seniority': 'thâm niên', 'joined': 'vào làm',
  'Raise every record that is below the statutory minimum for': 'Nâng tất cả hồ sơ thấp hơn mức tối thiểu luật định cho năm',
  'Records that already meet or exceed the minimum are left alone. Each change is written to the audit trail.':
    'Các hồ sơ đã đạt hoặc vượt mức tối thiểu sẽ được giữ nguyên. Mỗi thay đổi đều được ghi vào nhật ký kiểm toán.',
