  'Record': "Bản ghi",
  'With no printed expiry, the review treats a health examination as valid for 12 months — 6 for hazardous work, minors, elderly and disabled workers (OSH Law Art. 21(1)).': 'Nếu không in ngày hết hạn, khám sức khỏe được tính hiệu lực 12 tháng — 6 tháng với công việc nặng nhọc, người chưa thành niên, người cao tuổi và người khuyết tật (Điều 21(1) Luật ATVSLĐ).',
  'With no printed expiry, safety training is treated as valid for 2 years (Decree 44/2016 Art. 24), and only where the person has an OSH group set.': 'Nếu không in ngày hết hạn, huấn luyện an toàn được tính hiệu lực 2 năm (Điều 24 NĐ 44/2016), và chỉ khi người lao động đã được phân nhóm.',
