  'A quyết định records what the company decided about someone. The Labour Code governs two of them — a termination (Art. 34/36/45) and a disciplinary measure (Art. 122–127) — and those are checked before they can be issued.': 'Quyết định ghi nhận điều công ty đã quyết đối với người lao động. Bộ luật Lao động điều chỉnh hai loại — chấm dứt hợp đồng (Điều 34/36/45) và xử lý kỷ luật (Điều 122–127) — và hai loại này được kiểm tra trước khi ban hành.',
