  'These fields are what a signed document says the employer is. They are stated on every labour contract under Labour Code Art. 21(1)(a).': 'Các thông tin này là những gì một văn bản đã ký nói về người sử dụng lao động. Điều 21(1)(a) Bộ luật Lao động yêu cầu ghi trên mọi hợp đồng lao động.',
  'Admin access is required to change these — a contract issued afterwards would name whoever is set here.': 'Cần quyền quản trị để thay đổi — hợp đồng lập sau đó sẽ ghi tên người được đặt ở đây.',
