  'This form': 'Biểu mẫu này',
  'The term as drafted': 'Thời hạn đang soạn',
  'days': 'ngày',
  'Labour Code Art. 20 — a fixed term may not exceed 36 months, a replacement must be signed within 30 days of expiry, and a fixed term may be renewed only once. After that 30 days the contract has already become indefinite-term, whatever the file says.':
    'Bộ luật Lao động Đ.20 — hợp đồng xác định thời hạn không quá 36 tháng, phải ký hợp đồng mới trong vòng 30 ngày kể từ ngày hết hạn, và chỉ được ký thêm 01 lần. Quá 30 ngày đó, hợp đồng đã đương nhiên trở thành hợp đồng không xác định thời hạn, bất kể hồ sơ ghi gì.',
  'contract(s) need attention': 'hợp đồng cần xử lý',
  'Listed first below, worst case at the top.': 'Được liệt kê trước ở bảng dưới, trường hợp nghiêm trọng nhất ở trên cùng.',
  'Every contract is in order.': 'Tất cả hợp đồng đều hợp lệ.',
  'employee(s) checked.': 'nhân viên đã kiểm tra.',
  'Contract no.': 'Số hợp đồng', 'Term': 'Thời hạn', 'Days left': 'Số ngày còn lại',
  'Position under Art. 20': 'Tình trạng theo Đ.20', 'Indefinite': 'Không xác định thời hạn',
  'fixed terms so far': 'lần ký xác định thời hạn', 'no signed copy attached': 'chưa đính kèm bản đã ký',
  'No contract on file': 'Chưa có hợp đồng', 'Lapsed — now indefinite by law': 'Đã quá hạn — nay là HĐ không xác định thời hạn theo luật',
  'Expired — 30-day window': 'Đã hết hạn — còn trong 30 ngày', 'No end date': 'Chưa có ngày kết thúc',
  'Expiring': 'Sắp hết hạn', 'Active': "Đang làm", 'Indefinite-term': 'Không xác định thời hạn',
  // ── Correcting an attendance record ──
  'Correct': 'Sửa', 'corrected': 'đã sửa', 'Correct attendance': 'Sửa chấm công',
 'Check-out': "Giờ ra", 'Overtime hours': 'Số giờ làm thêm',
  'Overtime on this record is already approved. Changing the times or the hours sends it back for a decision — the approval described the shift as it was.':
    'Giờ làm thêm của bản ghi này đã được duyệt. Việc thay đổi giờ hoặc số giờ sẽ đưa nó trở lại chờ duyệt — phê duyệt trước đó áp dụng cho ca làm việc như cũ.',
  'Reason for the correction': 'Lý do sửa',
  'e.g. forgot to check out; site sign-out sheet shows 18:30': 'ví dụ: quên chấm công ra; sổ ký ra tại công trình ghi 18:30',
  'The before and after, your name and this reason go into the audit trail. Attendance feeds payroll, so a correction here can change what somebody is paid.':
    'Giá trị trước và sau, tên bạn và lý do này sẽ được ghi vào nhật ký kiểm toán. Chấm công là căn cứ tính lương, nên việc sửa ở đây có thể làm thay đổi số tiền nhân viên được nhận.',
  'Save correction': 'Lưu chỉnh sửa',
  'Give a reason for the correction — it goes on the record': 'Vui lòng nhập lý do sửa — lý do này sẽ được lưu vào hồ sơ',
  'Nothing was changed': 'Không có thay đổi nào', 'Attendance corrected': 'Đã sửa chấm công',
  'overtime sent back for approval': 'giờ làm thêm được gửi lại để duyệt',
  // ── Certificates, licences & health checks ──
  'Certificates, licences &amp; health checks': 'Chứng chỉ, giấy phép &amp; khám sức khỏe',
  'Law on OSH 2015 Art. 21(1) — a health examination at least once a year, and every six months for hazardous work, minors, elderly and disabled workers · Decree 44/2016 Art. 24 — safety training valid 2 years, where the company has classified somebody into a group.':
    'Luật ATVSLĐ 2015 Đ.21(1) — khám sức khỏe định kỳ ít nhất 1 lần/năm, và 6 tháng/lần với công việc nặng nhọc độc hại, người chưa thành niên, người cao tuổi và người khuyết tật · NĐ 44/2016 Đ.24 — chứng chỉ huấn luyện an toàn có giá trị 2 năm, với những người đã được phân nhóm.',
  'person(s) not fully covered': 'người chưa đủ điều kiện',
  'Missing and expired first. A certificate on file that lapsed is not cover.': 'Thiếu và hết hạn xếp trước. Chứng chỉ có trong hồ sơ nhưng đã hết hạn thì không còn giá trị.',
  'Everybody is covered.': 'Tất cả đều đủ điều kiện.',
