  'It goes into the normal approval and disbursement path. A settlement can only ever be raised once.': 'Khoản này sẽ đi theo quy trình duyệt và chi thông thường. Mỗi khoản thanh toán nghỉ việc chỉ được lập một lần duy nhất.',
  'This settlement was already raised.': 'Khoản thanh toán này đã được lập trước đó.',
