  // ── Payroll journal (Circular 200/2014) ──
  'Payroll journal': 'Bút toán tiền lương', 'Account': 'Tài khoản', 'Account name': 'Tên tài khoản',
  'Debit': 'Nợ', 'Credit': 'Có',
  'From the pay run the Director signed, not a recomputation of it': 'Lấy từ bảng lương Giám đốc đã ký, không phải tính lại',
  'No journal for': 'Chưa có bút toán cho',
  'A journal comes from a pay run a Director has signed. A draft is a proposal, and proposals do not belong in a ledger.': 'Bút toán chỉ sinh ra từ bảng lương đã được Giám đốc ký. Bản nháp chỉ là đề xuất, và đề xuất thì không được ghi sổ.',
  'Choose a specific month — a journal is posted per period.': 'Vui lòng chọn một tháng cụ thể — bút toán được ghi theo từng kỳ.',
  'These entries do not balance — do not post them': 'Bút toán không cân — không được ghi sổ',
  'Debits and credits differ. It has been recorded in the audit trail; the difference has to be explained before this is posted.': 'Tổng Nợ và tổng Có không khớp. Việc này đã được ghi vào nhật ký kiểm toán; cần giải trình chênh lệch trước khi ghi sổ.',
  // ── Salary payment file ──
  'Salary payment file': 'File chi lương', 'Choose a specific month.': 'Vui lòng chọn một tháng cụ thể.',
  'Produce the salary payment file for': 'Tạo file chi lương cho kỳ',
  'Check this total against the pay run before you release the batch in the bank portal — it is the last point the whole month can still be caught.':
    'Hãy đối chiếu tổng số này với bảng lương trước khi duyệt lô lệnh trên cổng ngân hàng — đây là điểm cuối cùng còn có thể phát hiện sai sót của cả tháng.',
  'Payment file produced': 'Đã tạo file chi lương', 'Produce it again anyway?': 'Vẫn tạo lại?',
  'The payment file cannot be produced yet': 'Chưa thể tạo file chi lương',
  'These people have no usable bank details, so the file would be missing them:': 'Những người sau chưa có thông tin ngân hàng hợp lệ nên sẽ bị thiếu trong file:',
  'A file missing one row uploads cleanly and looks correct. Add their bank details on the employee record, then try again.':
    'File thiếu một dòng vẫn tải lên bình thường và trông vẫn đúng. Vui lòng bổ sung thông tin ngân hàng trên hồ sơ nhân viên rồi thử lại.',
  'the figures below are the grade band mid-point, not this employee’s pay. Enter their agreed salary before issuing this payslip.': 'các con số dưới đây là mức giữa của khung bậc lương, không phải lương của nhân viên này. Vui lòng nhập mức lương đã thỏa thuận trước khi phát hành phiếu lương.',
  'Payroll cannot be run yet': 'Chưa thể chạy bảng lương',
  'Set each one’s monthly gross on their employee record, then try again.': 'Vui lòng nhập lương gộp hằng tháng trên hồ sơ của từng người, rồi thử lại.',
