  'Unpaid Break': 'Nghỉ giữa giờ không lương', 'Unpaid Break (min)': 'Nghỉ giữa giờ không lương (phút)',
  'The mid-shift break inside these hours. Art. 109 requires at least 30 consecutive minutes on a day of 6 hours or more, 45 where 3 or more hours fall between 22:00 and 06:00. It only counts as paid working time for continuous shift work (Decree 145 Art. 63(3)). Working-time compliance is measured after this comes off.':
    'Thời gian nghỉ giữa giờ trong ca. Điều 109 yêu cầu ít nhất 30 phút liên tục nếu làm việc từ 6 giờ trở lên trong ngày, 45 phút nếu có từ 3 giờ trở lên trong khoảng 22:00–06:00. Chỉ được tính vào giờ làm việc có hưởng lương đối với ca liên tục (khoản 3 Điều 63 Nghị định 145). Việc kiểm tra giờ làm việc được tính sau khi trừ khoảng này.',
