  'Standard hours 08:00–17:00, Mon–Fri; flexible/site schedules by arrangement.': 'Giờ làm việc chuẩn 08:00–17:00, Thứ 2–Thứ 6; lịch linh hoạt/công trường theo thỏa thuận.',
  'Annual leave accrues per your grade; apply via Leave Management for manager approval.': 'Phép năm tích lũy theo cấp bậc; đăng ký qua mục Quản lý nghỉ phép để quản lý phê duyệt.',
  'Treat colleagues, clients and partners with respect and professionalism.': 'Đối xử với đồng nghiệp, khách hàng và đối tác bằng sự tôn trọng và chuyên nghiệp.',
  'Harassment, discrimination, bullying or retaliation of any kind is prohibited.': 'Nghiêm cấm mọi hành vi quấy rối, phân biệt đối xử, bắt nạt hoặc trả đũa.',
  'Avoid conflicts of interest; disclose any that arise to HR.': 'Tránh xung đột lợi ích; khai báo với Nhân sự khi phát sinh.',
  'Report concerns to your manager or HR; reports are handled confidentially.': 'Báo cáo lo ngại cho quản lý hoặc Nhân sự; mọi báo cáo được xử lý bảo mật.',
  'Keep credentials private; enable MFA; never share passwords.': 'Giữ kín thông tin đăng nhập; bật MFA; không bao giờ chia sẻ mật khẩu.',
  'Handle personal data lawfully and only for legitimate business purposes.': 'Xử lý dữ liệu cá nhân đúng luật và chỉ cho mục đích kinh doanh hợp pháp.',
  'Wear required PPE; follow LOTO, working-at-height and confined-space rules.': 'Mang đầy đủ PPE; tuân thủ quy định LOTO, làm việc trên cao và không gian hạn chế.',
  'basic (65%) + position allowance (from G5).': 'lương cơ bản (65%) + phụ cấp chức vụ (từ G5).',
  'responsibility (10%) + skill/seniority (0–5%).': 'trách nhiệm (10%) + kỹ năng/thâm niên (0–5%).',
  'KPI bonus (10% × 0.5–1.5× by PADR rating).': 'thưởng KPI (10% × 0.5–1.5× theo xếp hạng PADR).',
  'Welfare: lunch ₫730,000 / phone ₫300,000 / transport ₫500,000 per month (non-SI).': 'Phúc lợi: ăn trưa ₫730,000 / điện thoại ₫300,000 / đi lại ₫500,000 mỗi tháng (không tính BHXH).',
  'Statutory SI/HI/UI 10.5% (employee) and PIT are withheld per law.': 'BHXH/BHYT/BHTN 10,5% (người lao động) và thuế TNCN được khấu trừ theo luật.',
