  "Automatic mailbox sync is OFF on the server: it has not loaded the Microsoft secret. On the server, set TK_M365_CLIENT_SECRET in .env and run ./deploy.sh to restart.": "Đồng bộ hòm thư tự động đang TẮT trên máy chủ: chưa nạp khóa bí mật Microsoft. Trên máy chủ, đặt TK_M365_CLIENT_SECRET trong .env rồi chạy ./deploy.sh để khởi động lại.",
