  "Procurement service isn’t running": "Dịch vụ Mua hàng chưa chạy",
  "Procurement didn’t finish loading": "Mua hàng chưa tải xong",
  "Couldn’t open Procurement": "Không thể mở Mua hàng",
  "You are signed in, but your account does not have the Procurement app switched on.": "Bạn đã đăng nhập, nhưng tài khoản của bạn chưa được bật ứng dụng Mua hàng.",
  "The portal cannot create a Procurement sign-on token because the shared secret is missing on the server.": "Cổng thông tin không thể tạo mã đăng nhập Mua hàng vì khóa bí mật dùng chung bị thiếu trên máy chủ.",
  "The portal created a sign-on token but Procurement did not accept it and asked to log in again — this almost always means the shared secret is different on the two apps.": "Cổng thông tin đã tạo mã đăng nhập nhưng Mua hàng không chấp nhận và yêu cầu đăng nhập lại — hầu như luôn có nghĩa là khóa bí mật dùng chung khác nhau giữa hai ứng dụng.",
  "The address /procurement served the portal instead of the Procurement app, which means the Procurement container is not up.": "Địa chỉ /procurement trả về cổng thông tin thay vì ứng dụng Mua hàng, nghĩa là container Mua hàng chưa hoạt động.",
  "The Procurement app did not respond in time.": "Ứng dụng Mua hàng không phản hồi kịp thời.",
  "An unexpected error occurred while opening Procurement.": "Đã xảy ra lỗi không mong muốn khi mở Mua hàng.",
  "Ask an administrator to tick “Procurement” for you in HR Admin → Access & Permissions.": "Đề nghị quản trị viên tích chọn “Mua hàng” cho bạn trong Quản trị NS → Phân quyền.",
  "On the VPS: set TK_SSO_SECRET in .env (a long random value), run ./update.sh, then hard-refresh.": "Trên VPS: đặt TK_SSO_SECRET trong .env (một giá trị ngẫu nhiên dài), chạy ./update.sh, rồi tải lại trang (hard-refresh).",
  "On the VPS: make sure TK_SSO_SECRET is set, then rebuild Procurement so it picks up the SAME value — ./update.sh — and hard-refresh.": "Trên VPS: đảm bảo TK_SSO_SECRET đã được đặt, rồi build lại Mua hàng để nó dùng CÙNG một giá trị — ./update.sh — và tải lại trang (hard-refresh).",
  "On the VPS: run ./update.sh (it builds Procurement + migrates its database), then check: docker ps | grep proc.": "Trên VPS: chạy ./update.sh (nó build Mua hàng + di trú cơ sở dữ liệu), rồi kiểm tra: docker ps | grep proc.",
  "Check the Procurement container is running on the VPS (docker ps | grep proc), then Retry.": "Kiểm tra container Mua hàng đang chạy trên VPS (docker ps | grep proc), rồi Thử lại.",
  "Please Retry. If it keeps happening, run ./update.sh on the VPS.": "Vui lòng Thử lại. Nếu vẫn tiếp diễn, chạy ./update.sh trên VPS.",
