  "Could not read the appraisal ratings — refusing to produce a run rather than paying everybody the neutral rating.": "Không đọc được kết quả đánh giá — hệ thống từ chối lập bảng lương thay vì trả cho tất cả mọi người theo mức đánh giá trung bình.",
  "The approved overtime for the month(s) below could not be loaded, so every payslip would show none — which is a wrong figure, not a missing one, and a signed run makes it permanent.": "Không tải được số giờ làm thêm đã duyệt của (các) tháng dưới đây, nên mọi phiếu lương sẽ hiển thị bằng không — đó là số liệu SAI chứ không phải số liệu thiếu, và một bảng lương đã ký thì không sửa được nữa.",
  "This is required to mark the payment paid, and is filed with the request, approval and invoice.": "Chứng từ này bắt buộc để đánh dấu đã thanh toán, và được lưu cùng đề nghị, phê duyệt và hóa đơn.",
