  "This rewrites every percentage already reported against it — e.g. \"Variation VO-014 reduced the run\".": "Việc này viết lại mọi phần trăm đã báo cáo theo con số cũ — VD: \"Phát sinh VO-014 giảm chiều dài tuyến\".",
  "Write the response before closing — a closed comment with no answer against it is how an objection goes missing.": "Hãy ghi nội dung trả lời trước khi đóng — một ý kiến đóng lại mà không có câu trả lời chính là cách một phản biện bị bỏ quên.",
  "The hours this estimate promises, by trade. These are the only physical quantities in a build-up that can later be checked against what actually happened — Projects → Labour cost reports the real cost per hour of a finished job, on a stated basis of recorded or allocated. Comparing the two is how next year’s estimate stops being a guess.": "Số giờ công mà dự toán này cam kết, theo từng bộ môn. Đây là những đại lượng vật lý duy nhất trong phần bóc tách có thể đối chiếu về sau với thực tế — Dự án → Chi phí nhân công cho biết chi phí thật trên mỗi giờ công của một công trình đã xong, trên cơ sở đã ghi nhận hoặc phân bổ. So sánh hai con số này là cách để dự toán năm sau không còn là phỏng đoán.",
