  "Library board": "Bảng thư viện",
  "Leave without saving?": "Rời đi mà chưa lưu?",
  "The Company Portal has changes that have not been saved. Leaving this tab keeps them in the editor, but they are not published until you press Save Portal Content.": "Cổng thông tin công ty có thay đổi chưa được lưu. Rời tab này vẫn giữ chúng trong trình soạn thảo, nhưng chúng chưa được công bố cho đến khi bạn nhấn Lưu nội dung cổng thông tin.",
  "Leave the tab": "Rời tab",
  "and more — narrow the search": "và còn nữa — hãy thu hẹp tìm kiếm",
  "This folder holds more than the portal will list at once. Use the search box to narrow it.": "Thư mục này có nhiều tệp hơn số cổng thông tin liệt kê một lần. Hãy dùng ô tìm kiếm để thu hẹp.",
  "More not shown": "Còn nữa chưa hiển thị",
  "No activities yet.": "Chưa có công việc nào.",
  "from Detail Schedule": "từ Tiến độ chi tiết",
  "daily progress": "tiến độ hằng ngày",
  "Calculated — not entered here": "Được tính tự động — không nhập ở đây",
  "Enter the accumulated total for each activity. Leave a row unchanged and nothing is filed against it.": "Nhập tổng lũy kế cho từng công việc. Dòng nào giữ nguyên thì không ghi nhận gì.",
  "can be entered here; the rest are calculated.": "có thể nhập ở đây; phần còn lại được tính tự động.",
  "Nothing changed — no progress filed.": "Không có thay đổi — chưa ghi nhận tiến độ nào.",
