  "rolled up": "tổng hợp lên",
  "No forecast yet: a forecast at completion needs earned value, and none has been recorded against this project.": "Chưa có dự báo: dự báo chi phí khi hoàn thành cần giá trị thu được, mà dự án này chưa ghi nhận giá trị nào.",
  "consultant time and expenses": "thời gian và chi phí của tư vấn",
