  "not stated": "chưa nêu",
  "Basis of estimate": "Cơ sở lập dự toán",
  "A price is only meaningful against a scope. Whatever a client assumes was included, was.": "Một mức giá chỉ có ý nghĩa khi gắn với phạm vi. Những gì khách hàng hiểu là đã bao gồm thì coi như đã bao gồm.",
  "What the money is spent on": "Tiền được chi vào đâu",
  "Of the cost base, not the selling price — so it does not move when somebody edits the margin.": "Tính trên giá thành, không phải giá bán — nên không thay đổi khi có người sửa tỷ suất lợi nhuận.",
  "Per": "Trên mỗi",
  "a total cannot be compared with the last job; a rate can.": "một con số tổng thì không so được với công trình trước; một đơn giá thì so được.",
  "No benchmark quantity set, so this tender cannot be compared with any other. Set one in Assumptions — floor area, airflow, units — and every figure here becomes a rate.": "Chưa đặt khối lượng chuẩn để đối chiếu, nên hồ sơ thầu này không so sánh được với hồ sơ nào khác. Hãy đặt một giá trị trong mục Giả định — diện tích sàn, lưu lượng gió, số bộ — và mọi con số ở đây sẽ thành đơn giá.",
  "Budget (cost base)": "Ngân sách (giá thành)",
  "Lines": "Số dòng",
  "Profit held back": "Lợi nhuận giữ lại",
  "Recoverable VAT excluded": "Không gồm VAT được khấu trừ",
  "What the job is funded for. The selling price and the profit are deliberately not here — a project that spends its profit has not stayed within budget, it has consumed the reason the job was taken.": "Số tiền công trình được cấp để thực hiện. Giá bán và lợi nhuận cố ý không nằm ở đây — một dự án tiêu vào lợi nhuận không phải là giữ được ngân sách, mà là ăn mất lý do nhận việc.",
  "Nothing priced yet, so there is nothing to hand over.": "Chưa định giá gì nên chưa có gì để chuyển giao.",
  "Already the budget for": "Đã là ngân sách của",
  "Re-baselining a live job is a decision, not a re-click — raise a revised tender instead.": "Đặt lại mốc chuẩn cho một công trình đang chạy là một quyết định, không phải bấm lại — hãy lập hồ sơ thầu sửa đổi.",
