  "The payroll journal refuses this rather than choosing which run wins. Cancel or supersede the duplicate.": "Bút toán tiền lương từ chối trường hợp này thay vì tự chọn bảng lương nào thắng. Hãy hủy hoặc thay thế bảng lương trùng.",
