  "One row per comment. Each carries the document and revision it is against, where on the sheet, who raised it, how serious it is, and a": "Mỗi ý kiến một dòng. Mỗi dòng ghi tài liệu và phiên bản bị góp ý, vị trí trên bản vẽ, người nêu, mức độ nghiêm trọng, và một",
