  "from likelihood × severity, initial and residual. A rating somebody typed is a number that can disagree with its own inputs.": "từ khả năng xảy ra × mức độ nghiêm trọng, cả ban đầu và tồn dư. Một mức điểm do người dùng gõ tay là con số có thể mâu thuẫn với chính đầu vào của nó.",
