  "Until that is written down the risk is still ours, and any drawing they sit on will not issue for construction.": "Chừng nào điều đó chưa được ghi lại thì rủi ro vẫn là của chúng ta, và bản vẽ liên quan sẽ không được phát hành thi công.",
  "deviation": "sai lệch",
  "is asked for before the fact: the design cannot meet a clause and proposes something else, with the reasoning that makes it acceptable. A": "được xin trước khi làm: thiết kế không đáp ứng được một điều khoản và đề xuất phương án khác, kèm lập luận cho thấy phương án đó chấp nhận được. Một",
