  "Nothing is linked to the Master Schedule yet.": "Chưa có liên kết nào với Tiến độ tổng.",
  "Use Link on a row to choose the activities that deliver it — progress, due date and status then follow the schedule.": "Bấm Gắn trên một dòng để chọn các công việc tạo ra gói đó — tiến độ, hạn hoàn thành và trạng thái sẽ bám theo tiến độ.",
  "Progress, due date and status are read from the master-schedule activities linked to each package. A package with none keeps the values typed on it.": "Tiến độ, hạn hoàn thành và trạng thái được lấy từ các công việc trong Tiến độ tổng gắn với từng gói. Gói chưa gắn công việc nào vẫn giữ số liệu nhập tay.",
  // ── Geofence zones: the Active toggle and the Department scope, now that they decide something ──
