  "margin now": "biên lợi nhuận hiện là",
  "rate(s)": "đơn giá",
  "This tender is a live project budget — it can be previewed but not re-priced.":
    "Hồ sơ này đang là ngân sách của dự án đang chạy — chỉ xem thử, không cập nhật được.",


