  'Import bill': 'Nhập bảng khối lượng',
  'Import or enter the bill of quantities. A line with no rate is reported as unpriced — never valued at nil.': 'Nhập hoặc khai báo bảng khối lượng. Dòng không có đơn giá được báo là chưa có giá — không bao giờ được tính bằng 0.',
  'Import the bill of quantities': 'Nhập bảng khối lượng',
  'Import the priced bill from the contract — everything on this tab is measured against it.': 'Nhập bảng khối lượng đã có đơn giá từ hợp đồng — mọi thứ trong tab này được đo bóc theo bảng đó.',
  'Importing': 'Đang nhập',
  'Instructed and being built, with no agreed price behind it.': 'Đã có chỉ thị và đang thi công nhưng chưa thống nhất được giá.',
  'Instructed on': 'Ngày chỉ thị',
  'Instruction': 'Chỉ thị',
  'Instruction recorded': 'Đã ghi nhận chỉ thị',
  'Instruction reference': 'Số chỉ thị',
  'Interim Valuations & Payment Applications': 'Định giá đợt & Hồ sơ thanh toán',
  'Kind is optional and defaults to a measured item; use heading, provisional, pcsum or note for the others. A BLANK RATE STAYS BLANK — it is reported as unpriced, never valued at nil.': 'Cột loại dòng không bắt buộc, mặc định là hạng mục đo bóc; dùng heading, provisional, pcsum hoặc note cho các loại khác. ĐƠN GIÁ ĐỂ TRỐNG SẼ GIỮ NGUYÊN TRỐNG — được báo là chưa có giá, không bao giờ tính bằng 0.',
  'Known future losses: rework, damages, disputed variations.': 'Thiệt hại đã biết trong tương lai: làm lại, phạt, phát sinh đang tranh chấp.',
  'Less certified to date': 'Trừ lũy kế đã xác nhận',
