  'Mark as paid': 'Đánh dấu đã thanh toán',
  'Material delivered and paid for but not yet built in. Set the incorporation date when it is installed and it leaves the valuation — otherwise the same pump is claimed twice.': 'Vật tư đã về công trường và đã trả tiền nhưng chưa lắp đặt. Khi lắp xong, hãy điền ngày lắp đặt để nó rời khỏi đợt định giá — nếu không, cùng một chiếc bơm sẽ bị tính tiền hai lần.',
  'Materials on Site': 'Vật tư tại công trường',
