  'Measurement sheet (PDF)': 'Bảng đo bóc (PDF)',
  'No QS files yet — anything attached to a measurement, a variation, a daywork sheet or a materials record appears here.': 'Chưa có tệp QS nào — mọi tệp đính kèm ở bản đo bóc, phát sinh, phiếu công nhật hoặc vật tư sẽ hiện tại đây.',
  'No bill of quantities yet': 'Chưa có bảng khối lượng',
  'No date, so this record cannot be placed in a period and is excluded from every valuation.': 'Không có ngày nên không xếp được vào kỳ nào và bị loại khỏi mọi đợt định giá.',
  'No daywork sheets': 'Chưa có phiếu công nhật',
  'No materials on site recorded': 'Chưa ghi nhận vật tư tại công trường',
  'No measurement recorded yet': 'Chưa ghi nhận đo bóc',
  'No rate — this line is excluded from every total, and is not worth nil.': 'Chưa có đơn giá — dòng này bị loại khỏi mọi tổng cộng, và không có nghĩa là bằng 0.',
  'No valuation opened yet': 'Chưa mở đợt định giá nào',
  'No variations recorded': 'Chưa ghi nhận phát sinh',
  'Not a final account yet': 'Chưa phải là quyết toán',
  'Not counted': 'Không được tính',
  'Not yet': 'Chưa',
  'Nothing certified yet.': 'Chưa xác nhận khoản nào.',
  'Nothing to import — check the columns.': 'Không có gì để nhập — hãy kiểm tra lại các cột.',
  'Nothing unexplained': 'Không có gì chưa giải thích được',
  'Open a valuation. Measured works + agreed variations + approved daywork + materials on site.': 'Mở đợt định giá. Khối lượng đo bóc + phát sinh đã thống nhất + công nhật đã duyệt + vật tư tại công trường.',
  'Open an interim valuation': 'Mở đợt định giá',
  'Open draft': 'Bản nháp đang mở',
  'Open valuation': 'Mở đợt định giá',
  'Original': 'Gốc',
  'Original sum + agreed variations + provisional adjustments + daywork + agreed claims. It refuses to call itself agreed while anything in it is not.': 'Giá trị hợp đồng gốc + phát sinh đã thống nhất + điều chỉnh tạm tính + công nhật + khiếu nại đã thống nhất. Hệ thống không tự nhận là đã thống nhất khi còn khoản chưa thống nhất.',
  'Over-measured lines': 'Số dòng đo vượt',
  'Paste straight out of Excel, or drop a CSV. Columns, in order:': 'Dán trực tiếp từ Excel hoặc chọn tệp CSV. Thứ tự các cột:',
  'Paste the project SharePoint folder link in Edit → SharePoint docs folder, then use Create in SharePoint on the Documents tab to build the QS folders.': 'Dán liên kết thư mục SharePoint của dự án ở Sửa → Thư mục tài liệu SharePoint, sau đó dùng Tạo trên SharePoint ở tab Tài liệu để tạo các thư mục QS.',
  'Payment application': 'Hồ sơ thanh toán',
  'Payment application submitted': 'Đã gửi hồ sơ thanh toán',
  'Payment date': 'Ngày thanh toán',
  'Price the bill': 'Lập giá bảng khối lượng',
  'Priced bill (PDF)': 'Bảng khối lượng có đơn giá (PDF)',
  'Progress against the revised contract sum': 'Tiến độ so với giá trị hợp đồng đã điều chỉnh',
  'Provisional / PC sum adjustment for the final account (₫)': 'Điều chỉnh khoản tạm tính / chỉ định cho quyết toán (₫)',
