  'How this company works, written down — policies, procedures, forms and guides. Every document is read straight from SharePoint, so what you see here is what HR published there.': 'Cách công ty vận hành, được ghi lại — chính sách, quy trình, biểu mẫu và hướng dẫn. Mọi tài liệu được đọc trực tiếp từ SharePoint, nên những gì bạn thấy ở đây đúng là những gì Nhân sự đã đăng ở đó.',
  'What the company has learned and teaches — training material, technical know-how and reference documents from the Learning Management System.': 'Những gì công ty đã đúc kết và giảng dạy — tài liệu huấn luyện, bí quyết kỹ thuật và tài liệu tham khảo từ Hệ thống quản lý học tập.',
