  'Demo mode': 'Chế độ demo',
  'Documents are read live from SharePoint, which the demo has no session for. The links still work.': 'Tài liệu được đọc trực tiếp từ SharePoint, bản demo không có phiên đăng nhập cho việc đó. Các liên kết vẫn hoạt động.',
  'Sign in to Microsoft 365': 'Đăng nhập Microsoft 365',
  'Sign in to Microsoft 365 to read the documents here': 'Đăng nhập Microsoft 365 để đọc tài liệu tại đây',
  'Files stay in SharePoint and are shown with your own permissions, so this needs your Microsoft session. You can open the library in SharePoint instead.': 'Tệp vẫn nằm trong SharePoint và hiển thị theo đúng quyền của bạn, nên cần phiên Microsoft của bạn. Bạn cũng có thể mở thư viện trực tiếp trong SharePoint.',
  'The portal will hand you to Microsoft to sign in, then bring you back here. Anything you have typed on another screen will be lost.': 'Cổng thông tin sẽ chuyển bạn sang Microsoft để đăng nhập, rồi đưa bạn trở lại đây. Mọi nội dung bạn đã nhập ở màn hình khác sẽ bị mất.',
