  'Access restricted — Daily Report is not enabled for your account. Ask an admin.': 'Không có quyền truy cập — Báo cáo hằng ngày chưa được bật cho tài khoản của bạn. Vui lòng liên hệ quản trị viên.',
  'Back to the report': 'Quay lại báo cáo',
  'A daily report belongs to one contractor on this project. Set each contractor up once — its logo, the roles and trades its tables count, and the SharePoint lists its site fills in — and every day after that arrives on its own.': 'Mỗi báo cáo hằng ngày thuộc về một nhà thầu trên dự án này. Thiết lập từng nhà thầu một lần — logo, các vị trí và tổ đội mà bảng của họ đếm, và các danh sách SharePoint mà công trường điền — sau đó mỗi ngày báo cáo sẽ tự về.',
  'Search this report…': 'Tìm trong báo cáo này…',
  'This project’s report header': 'Phần đầu báo cáo của dự án này',
  'The project name, the client and the planned dates come from the project itself — edit them in the project, not here. What is below is only what the daily report adds on top.': 'Tên dự án, chủ đầu tư và các mốc thời gian kế hoạch lấy từ chính dự án — sửa ở phần dự án, không sửa ở đây. Bên dưới chỉ là những gì báo cáo hằng ngày bổ sung thêm.',
  'Project SharePoint folder': 'Thư mục SharePoint của dự án',
  'Every photo and file the site submits is filed under this folder, in Daily Report / contractor / month / day. A contractor with no Microsoft account cannot attach a photo to a form — Microsoft Forms offers file upload only to people signed in to your organisation — so give them a SharePoint upload link to this folder instead, and the report will find the photos there.': 'Mọi hình ảnh và tệp công trường gửi lên được lưu trong thư mục này, theo Daily Report / nhà thầu / tháng / ngày. Nhà thầu không có tài khoản Microsoft không thể đính kèm ảnh vào biểu mẫu — Microsoft Forms chỉ cho tải tệp với người đã đăng nhập vào tổ chức của bạn — nên hãy gửi cho họ liên kết tải lên SharePoint trỏ vào thư mục này, báo cáo sẽ tự tìm thấy ảnh ở đó.',
  'No client logo yet': 'Chưa có logo chủ đầu tư',
  'Upload client logo': 'Tải lên logo chủ đầu tư',
  'Printed top-left on every page. The Humiley mark is fixed.': 'In ở góc trên bên trái mọi trang. Logo Humiley là cố định.',
  'Save project header': 'Lưu phần đầu dự án',
  'Project header saved': 'Đã lưu phần đầu dự án',
  'The contractor logo prints bottom-right on every page of this contractor’s report. Set it once.': 'Logo nhà thầu in ở góc dưới bên phải mọi trang báo cáo của nhà thầu này. Chỉ cần đặt một lần.',
  'One list per table, each row carrying its date and contractor. Paste the link to each. A list left blank contributes nothing — plenty of days have no defects list at all.': 'Mỗi bảng một danh sách, mỗi dòng mang theo ngày và nhà thầu của nó. Dán liên kết cho từng danh sách. Danh sách để trống thì không đóng góp gì — rất nhiều ngày không có danh sách lỗi.',
  'Daily Report': 'Báo cáo hằng ngày',
  'Open Report Setup': 'Mở Thiết lập báo cáo',
  'the export took too long and was stopped': 'quá trình xuất file mất quá lâu và đã dừng',
  'Build the forms': 'Tạo các biểu mẫu',
  'Building the form sheets…': 'Đang tạo bản hướng dẫn biểu mẫu…',
  'Do it in this order': 'Thực hiện theo thứ tự này',
  'The SharePoint lists': 'Các danh sách SharePoint',
  'This tenant has granted the permission a list needs, so the portal can create all twelve for you.': 'Tổ chức này đã cấp quyền cần thiết để tạo danh sách, nên cổng có thể tạo cả mười hai danh sách cho bạn.',
  'Creating a list needs Sites.Manage.All, and this app holds: {0}. So run the script below instead — it does the same thing and is safe to re-run.': 'Việc tạo danh sách cần quyền Sites.Manage.All, còn ứng dụng này đang có: {0}. Hãy chạy tập lệnh bên dưới — nó làm đúng việc đó và có thể chạy lại an toàn.',
  'Create the lists': 'Tạo các danh sách',
