  'A file-upload question cannot exist on a form that anyone can respond to. Leave this question out and collect the photos through the SharePoint upload link.': 'Câu hỏi tải tệp lên không thể tồn tại trên biểu mẫu mà ai cũng trả lời được. Hãy bỏ câu hỏi này và thu thập hình ảnh qua liên kết tải lên SharePoint.',
