  'Could not reach the clipboard, so the script was downloaded instead.': 'Không truy cập được bộ nhớ tạm, nên tập lệnh đã được tải xuống.',
  'Who may open the form': 'Ai được mở biểu mẫu',
  'The site’s own form link': 'Liên kết biểu mẫu riêng của công trường',
  'This contractor fills the daily report in through its own permanent link — no Microsoft account needed. The link never changes. It is not a password: opening it asks for one of the email addresses below, and sends a six-digit code there.': 'Nhà thầu này điền báo cáo hằng ngày qua liên kết cố định của riêng họ — không cần tài khoản Microsoft. Liên kết không bao giờ thay đổi. Nó không phải mật khẩu: khi mở, hệ thống hỏi một trong các địa chỉ email bên dưới và gửi mã sáu chữ số tới đó.',
  'One address per line': 'Mỗi dòng một địa chỉ',
  'Only these addresses can open the form. Removing one takes effect immediately, even on a phone that was already signed in.': 'Chỉ những địa chỉ này mới mở được biểu mẫu. Xóa một địa chỉ có hiệu lực ngay lập tức, kể cả trên điện thoại đã đăng nhập từ trước.',
  'Show the link': 'Hiện liên kết',
  'Email the link': 'Gửi liên kết qua email',
  'Sign everyone out': 'Đăng xuất tất cả',
  'Issue a new link': 'Cấp liên kết mới',
  'The link': 'Liên kết',
  'Sent.': 'Đã gửi.',
  'Last emailed {0} to {1}': 'Gửi lần cuối ngày {0} tới {1}',
  'from {0}': 'từ {0}',
  'Sign every device out of this contractor’s form?\n\nThe link still works. Anyone still on the list can sign in again with a new code.': 'Đăng xuất mọi thiết bị khỏi biểu mẫu của nhà thầu này?\n\nLiên kết vẫn hoạt động. Ai còn trong danh sách vẫn đăng nhập lại được bằng mã mới.',
  'Every device has been signed out. The link still works.': 'Mọi thiết bị đã được đăng xuất. Liên kết vẫn hoạt động.',
  'Could not sign devices out': 'Không đăng xuất được các thiết bị',
  'Issue a new link for this contractor?\n\nEvery copy of the old link stops working, including any the site has bookmarked — so it has to be emailed out again.': 'Cấp liên kết mới cho nhà thầu này?\n\nMọi bản sao của liên kết cũ sẽ ngừng hoạt động, kể cả liên kết công trường đã lưu — nên phải gửi lại qua email.',
  'A new link has been issued. Email it to the site — the old one no longer works.': 'Đã cấp liên kết mới. Hãy gửi cho công trường — liên kết cũ không còn dùng được.',
  'Could not issue a new link': 'Không cấp được liên kết mới',
  'Because every row names its contractor, ONE set of twelve lists can serve every contractor on the project — the sync only reads the rows that name this one. Build them once, then copy the links to each contractor below. Separate lists per contractor also work, if a client wants them kept apart.': 'Vì mỗi dòng đều ghi rõ nhà thầu, MỘT bộ mười hai danh sách có thể dùng chung cho mọi nhà thầu của dự án — khi đồng bộ, hệ thống chỉ đọc những dòng ghi tên nhà thầu này. Tạo một lần, rồi sao chép liên kết sang từng nhà thầu bên dưới. Vẫn có thể tách riêng danh sách cho từng nhà thầu, nếu khách hàng muốn để riêng.',
  'Use the same lists as': 'Dùng chung danh sách với',
  'Copy the links': 'Sao chép liên kết',
  '{0} link(s) copied from {1}. Press Save setup to keep them.': 'Đã sao chép {0} liên kết từ {1}. Bấm Lưu thiết lập để giữ lại.',
  'Nobody can open this link yet.': 'Hiện chưa ai mở được liên kết này.',
  'No address is saved for this contractor, so every attempt to sign in is refused — and the form still says a code is on its way, because it must not reveal who is on the list. Add an address above and press Save setup.': 'Chưa có địa chỉ nào được lưu cho nhà thầu này, nên mọi lần đăng nhập đều bị từ chối — mà biểu mẫu vẫn báo là mã đang được gửi, vì nó không được phép tiết lộ ai có trong danh sách. Hãy thêm địa chỉ ở trên rồi bấm Lưu thiết lập.',
  'Saved and in force': 'Đã lưu và đang có hiệu lực',
