  /* ── Hồ sơ nghiệm thu ────────────────────────────────────────────────────────────────────────
     The one screen in this portal whose PRIMARY audience reads Vietnamese: the site engineer, the
     supervision consultant and the client's PMU. So the vocabulary here is the register's own —
     "nghiệm thu", "hồ sơ", "biên bản", "tồn tại" — not a literal rendering of the English.
     Note that the LEGAL text (article numbers, the acceptance types, the standards) is not in here
     at all: it is served bilingual from acceptance.py, so there is nothing to keep in step. */
  "(no checklist — type the lines yourself)": "(không dùng checklist — tự nhập các mục)",
  "(no number)": "(chưa có số)",
  "A JSON file exported from this screen, or a CSV with one line per checklist item and these columns:": "Tệp JSON xuất từ màn hình này, hoặc tệp CSV mỗi dòng một mục kiểm tra với các cột sau:",
  "A form needs a code — it is what a minute cites.": "Biểu mẫu phải có mã số — biên bản sẽ trích dẫn mã này.",
  "A minute may be signed with items still outstanding — Nghị định 06/2021 Điều 24 khoản 3 — provided none of them affects load-bearing capacity, safety in use, or the function of the works. Any one of those three blocks the acceptance until it is closed.": "Biên bản vẫn có thể ký khi còn tồn tại — Nghị định 06/2021 Điều 24 khoản 3 — với điều kiện các tồn tại đó không ảnh hưởng khả năng chịu lực, an toàn sử dụng và công năng công trình. Chỉ cần một trong ba yếu tố đó là chưa thể nghiệm thu cho tới khi được khắc phục.",
  "ARF No.": "Số phiếu mời",
  "About the standards list": "Về danh mục tiêu chuẩn",
  "Acceptance date": "Ngày nghiệm thu",
  "Acceptance dossier register": "Sổ hồ sơ nghiệm thu",
  "Acceptance minute": "Biên bản nghiệm thu",
  "Acceptance plan": "Kế hoạch nghiệm thu",
  "Acceptance plan — inspections called": "Kế hoạch nghiệm thu — các lần đã mời",
  "Acceptance request": "Phiếu yêu cầu nghiệm thu",
  "Add a checklist line — Vietnamese | English": "Thêm mục kiểm tra — Tiếng Việt | English",
  "Adopt": "Nhận về dự án",
  "Already in a dossier": "Đã thuộc một bộ hồ sơ",
