  "Templates not yet reviewed": "Bản mẫu chưa rà soát",
  "The forms shipped with the portal are DRAFTS written against the standards they name — not transcriptions of an approved ITP, and not reviewed by anybody on this project. Copy one into the project, correct it against your own ITP and the current standard editions, then Review & adopt. A dossier compiled from a form that has not been adopted says so on its readiness panel.": "Các biểu mẫu đi kèm phần mềm là BẢN DỰ THẢO soạn theo tiêu chuẩn được nêu — không phải bản sao của một ITP đã phê duyệt, và chưa được ai trong dự án này rà soát. Hãy nhận về dự án, chỉnh lại theo ITP của mình và theo phiên bản tiêu chuẩn hiện hành, rồi bấm Rà soát & ban hành. Hồ sơ lập từ biểu mẫu chưa ban hành sẽ được ghi rõ trên bảng điều kiện nghiệm thu.",
  "WHO ATTENDS": "THÀNH PHẦN THAM DỰ",
  "What has to be with this minute": "Hồ sơ phải kèm theo biên bản",
  "Work in this stage gets covered up — photograph it and mark up the drawing before it is.": "Công việc giai đoạn này sẽ bị che khuất — hãy chụp ảnh và ghi chú lên bản vẽ trước khi che lấp.",
  "Yes — reviewed and adopted": "Đồng ý — đã rà soát và ban hành",
  "a convention, not a legal requirement; the contract may say otherwise.": "là thông lệ, không phải quy định bắt buộc; hợp đồng có thể quy định khác.",
  "adopted": "đã ban hành",
  "copied into this project — edit its lines, then Review & adopt": "đã nhận về dự án — chỉnh các mục kiểm tra rồi bấm Rà soát & ban hành",
  "has been checked against this project's ITP, its standard editions are current, and it is fit to carry a signed minute. Your name and today's date are recorded against it.": "đã được đối chiếu với ITP của dự án, phiên bản tiêu chuẩn còn hiệu lực, và đủ điều kiện dùng cho biên bản có chữ ký. Tên bạn và ngày hôm nay sẽ được ghi nhận.",
  "pass": "đạt",
