  "Counted from the stage each dossier names, not from the ITP — so this half of the screen works even before anything is linked.": "Tính theo giai đoạn ghi trên từng bộ hồ sơ, không phải theo ITP — nên phần này vẫn dùng được ngay cả khi chưa gắn liên kết nào.",
  "Dossiers not linked": "Hồ sơ chưa gắn",
