  "Inspection & Test Plans": "Kế hoạch kiểm tra và thí nghiệm (ITP)",
  "Link up": "Gắn liên kết",
  "No percentage is drawn while most dossiers are unlinked — it would be the most confident thing on this screen and the least true. The table below is still exact: it says what is linked.": "Chưa vẽ tỷ lệ phần trăm khi phần lớn hồ sơ chưa được gắn — đó sẽ là con số trông chắc chắn nhất màn hình nhưng sai nhất. Bảng dưới đây vẫn chính xác: nó cho biết những gì đã được gắn.",
  "Nothing could be suggested. Open each dossier and set its ITP by hand — a guess offered here would be confirmed by somebody clicking through, which is exactly what this screen refuses to do.": "Không có gợi ý nào. Hãy mở từng bộ hồ sơ và chọn ITP thủ công — một phỏng đoán đưa ra ở đây sẽ được bấm xác nhận cho xong, và đó chính là điều màn hình này từ chối làm.",
  "Nothing planned here yet — this register is empty.": "Chưa có kế hoạch nào — sổ đăng ký này đang trống.",
  "Nothing to measure against": "Chưa có căn cứ để đối chiếu",
  "Nothing to measure yet": "Chưa có gì để đo",
  "Read these figures as a floor, not a total": "Hãy đọc các con số này là mức tối thiểu, không phải tổng số",
  "Suggested links": "Gợi ý gắn liên kết",
  "Suggestions only — nothing is linked until you say so. A dossier is offered an ITP when it quotes that ITP's number, or when exactly one ITP in the same discipline carries the same title. An ambiguous title produces no suggestion at all rather than a coin toss.": "Chỉ là gợi ý — không có liên kết nào được tạo cho tới khi bạn xác nhận. Hồ sơ được gợi ý gắn với một ITP khi nó có ghi số hiệu ITP đó, hoặc khi trong cùng bộ môn chỉ có đúng một ITP trùng tên. Tên trùng nhiều nơi thì không gợi ý gì cả, thay vì chọn bừa.",
  "These figures can be reported as they stand": "Các số liệu này có thể dùng để báo cáo",
  "WBS accepted": "Hạng mục WBS đã nghiệm thu",
  "WBS packages": "Hạng mục WBS",
  "Work in this stage gets covered up": "Công việc giai đoạn này sẽ bị che khuất",
  "Work packages (WBS)": "Hạng mục công việc (WBS)",
  "concealed": "bị che khuất",
  "dossier(s) name no stage, so they appear in none of the rows above.": "bộ hồ sơ không ghi giai đoạn, nên không xuất hiện ở dòng nào phía trên.",
  "name a stage this app does not know — probably imported, or renamed.": "ghi một giai đoạn phần mềm không biết — có thể do nhập từ nguồn khác hoặc đã đổi tên.",
  "same discipline, and only one ITP has this title": "cùng bộ môn, và chỉ có một ITP trùng tên này",
