  "Evidence": "Căn cứ",
  "Held by": "Đơn vị lưu",
  "Index of the completed-works dossier": "Danh mục hồ sơ hoàn thành công trình",
  "Items on the list": "Số mục trong danh mục",
  "Nghị định 06/2021/NĐ-CP Điều 26, Phụ lục VIb. Rows marked “automatic” are counted from the registers in this app and cannot be ticked by hand — they show as held once the records exist. The rest are documents the portal has never seen, so they carry somebody's name and the date they confirmed it. Which rows a given works actually needs is a judgement for the project: strike off what does not apply, with a reason.": "Nghị định 06/2021/NĐ-CP Điều 26, Phụ lục VIb. Các dòng ghi “tự động” do phần mềm đếm từ sổ đăng ký và không tích tay được — chúng chuyển thành “đã có” khi thực sự có hồ sơ. Các dòng còn lại là tài liệu phần mềm chưa từng thấy, nên phải mang tên người xác nhận và ngày xác nhận. Công trình cụ thể cần những mục nào là do dự án quyết định: mục nào không áp dụng thì gạch đi và ghi lý do.",
  "Print the index": "In danh mục",
