  "The consultant and the client have no account here — they are the other side of the contract, so their addresses live with the project. A party with none recorded is why an invitation refuses to send, rather than something the send quietly skips.": "Tư vấn giám sát và chủ đầu tư không có tài khoản trên hệ thống này — họ là phía bên kia của hợp đồng, nên địa chỉ của họ được lưu theo dự án. Bên nào chưa khai báo địa chỉ thì thư mời sẽ bị từ chối gửi, thay vì lặng lẽ bỏ qua bên đó.",
  "This goes outside the company, to the consultant and the client. Check the addresses and the message below — nothing is sent until you press Send.": "Thư này gửi ra ngoài công ty, tới tư vấn giám sát và chủ đầu tư. Hãy kiểm tra địa chỉ và nội dung bên dưới — không có gì được gửi đi cho tới khi bạn bấm Gửi.",
